    public static class طهحسين
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "لو أن الإنسان خلق كاملاً لما احتاج إلى أن يطمع في الكمال", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "قد يكون المرء غبياً في طبعه لكن الغباء غباء القلب.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "القوانين حين تشتد في مصادرة حرية الرأي لا تحمي الفضيلة وإنما تحمي الرذيلة وتخلي بينها وبين النفوس", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "مصر خليقة أن يُحسب لها حساب حين ترضى، وأن يُحسب لها حساب حين تغضب، وأن يُحسب لها حساب حين تريد", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "إياك والرضا عن نفسك فإنه يضطرك إلى الخمول، وإياك والعجب فإنه يورطك في الحمق، وإياك والغرور فإنه يظهر للناس كلهم نقائصك كلها ولا يخفيها إلا عليك...", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "الذين لا يعملون يؤذي نفوسهم أن يعمل الناس", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "الأصدقاء ثلاث طبقات: طبقة كالغذاء لا نستغني عنه .. وطبقة كالدواء لا نحتاج إليه إلا أحيانا .. وطبقة كالداء لا نحتاج إليه أبدا ..", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "إن الجامعة تتألف من طالب حر وأستاذ حر.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "وهكذا جمعنا الزمان والمكان والشوق أما الزمان والمكان فلا ثبات لهما، وأما الشوق فلا يورث الا الحزن", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "الحنين إلى الوطن خالد لا يدري أحد أحديث هو أم قديم", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "ليس من الحق على الشاعر أن يقدم إليك فنه الرائع وأنت هادئ وادع مطمئن ناعم البال ، وإنما الحق عليك أن تجدّ كما جدّ ، وتتعب كما تعب ، وتشقى بالتماس الجمال كما شقي هو بعرض هذا الجمال.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "الفلسفة هي مظهر الحياة العقلية القوية. وهي وسيلة الانسان إلى أن يتصور الحقائق ويحكم عليها بعقله لا بخياله.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "ويل لطالب العلم إن رضي عن نفسه", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "فإذا ابتسم الصبح وأشرق الضحى واستيقظت الحياة ذابت كل المروعات", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "حذار .. فأننى لم أجد تجارة هى أربح من بيع الأحلام", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "الأوطان تُبنى بالعلم والعمل في كل ميدان.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "ما أعرف شيئاً يدفع النفس ولا سيما النفوس الناشئة إلى الحرية والإسراف فيها أحياناً كالأدب.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "التاريخ سخيف لا خير فيه إن كان يعيد نفسه، لأن ذلك يدل على أنه لم يستطع للناس وعظاً ولا إصلاحاً.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "مهما يبلغ الفقر بالناس، ومهما يثقل عليهم البؤس... فإن في فطرتهم شيئاً من كرامة تحملهم على أن يجدوا حين يأكلون مما كسبت أيديهم لذة لا يجدونها حين يأكلون مما يُساق إليهم دون أن يكسبوه أو يحتالوا فيه.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "أهدي كتابي هذا للّذين لا يعملون، ويؤلمهم أن يعمل الآخرون.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "ولكن المرأة لا تُغلب إلا إذا أحبّت، ولا تُقهر إلا إذا أرادت، ولا تُذعن إلا إذا رغبت في الإذعان.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "الندم وحده هو الذي يطهر القلوب ويهيئ النفوس للتوبة النصوح.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "السعادة هي ذلك الاحساس الغريب الذي يراودنا حينما تشغلنا ظروف الحياة عن أن نكون أشقياء.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "هذه هي الحياة أنك تتنازل عن متعك الواحدة بعد الأخرى حتى لا يبقي منها شيء وعندئذ تعلم أنه قد حان وقت الرحيل.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "إياك والرضى عن نفسك فانه يضطرك إلى الخمول.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "اياك والغرور فانه يظهر للناس كلهم نقائصك كلها ولا يخفيها الا عليك.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "كم أتمنى أن يقرأ الكاتب أكثر مما يكتب.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "وما عساك من القتل تجني غير الهدم والفناء.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "ما أكثر ما أعجب من نفسي ، وما أسرع ما يستحيل هذا العجب إل سخرية منها أول الأمر ، ثم إلى رثاء وعطف عليها.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "لمرض الذي لا أجد منه برءاً ، مرض التماس العلة والانتهاء إلى المصادر .", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "الأكل فن من الفنون لا بد فيه من الروية واصطناع المهل والأناة .", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "لا أنكر الحياة الجاهلية وإنما أنكر أن يمثلها هذا الشعر الذي يسمونه الشعر الجاهلي.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "الأمة الذليلة لا يمكن أن يكون لها شعر راق ، إلا في فن التضرع والاستعطاف.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "الإنسان مفطور على حب البحث ، والرغبة في الاستطلاع لكن الحياة وأطوارها قد تصرفه عن مقتضى هذه الفطرة.", Author = "طه حسين" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/طه_حسين", Text = "لا تنخدعوا .. لو كان للغة وزن في تقرير مصير الأمم ، لما كانت بلجيكا وسويسرا ولا أميركا ولا البرازيل ولا البرتغال .", Author = "طه حسين" },
        };
    }
}